import{_ as t,o as r,c as o,ah as a}from"./chunks/framework.C-FRNfAJ.js";const p=JSON.parse('{"title":"Modules du socle","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/core-modules.md","filePath":"src/guide/core-modules.md"}'),n={name:"guide/core-modules.md"};function s(i,e,l,d,u,c){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="modules-du-socle" tabindex="-1">Modules du socle <a class="header-anchor" href="#modules-du-socle" aria-label="Permalink to &quot;Modules du socle&quot;">​</a></h1><p>Les modules 1 à 18, 29 et 32 forment le socle. Cette page résume les règles qui structurent le quotidien ; le détail exhaustif vit dans la documentation de référence.</p><h2 id="catalogue-module-1" tabindex="-1">Catalogue (module 1) <a class="header-anchor" href="#catalogue-module-1" aria-label="Permalink to &quot;Catalogue (module 1)&quot;">​</a></h2><p>Un <strong>référentiel</strong> est une formation du catalogue, identifiée par un code stable et immuable <code>NB.XX.YY</code>. Le préfixe suit la catégorie :</p><table tabindex="0"><thead><tr><th>Catégorie</th><th>Code</th><th>Durée</th></tr></thead><tbody><tr><td>Parcours Métiers</td><td><code>NB.FP.01</code> – <code>NB.FP.10</code></td><td>500 h / 25 semaines + stage (700 h pour le package Développement Web &amp; Mobile)</td></tr><tr><td>Compétences Métiers</td><td><code>NB.CM.01</code> – <code>NB.CM.12</code></td><td>250 h / 12 semaines + stage</td></tr><tr><td>Technologies &amp; Outils</td><td><code>NB.TO.01</code> – <code>NB.TO.18</code></td><td>250 h / 12 semaines + stage</td></tr></tbody></table><p>Trois statuts : <strong>brouillon</strong>, <strong>publié</strong>, <strong>archivé</strong>. Seul un référentiel publié est visible sur le site. La dépublication est impossible s&#39;il est lié à une cohorte ouverte, confirmée ou en cours.</p><p>Le tarif n&#39;est jamais saisi librement : il dérive de la catégorie et du format, via la grille tarifaire.</p><table tabindex="0"><thead><tr><th>Catégorie</th><th>Distanciel</th><th>Hybride</th><th>Présentiel</th></tr></thead><tbody><tr><td>Parcours Métiers</td><td>850 000</td><td>900 000</td><td>950 000</td></tr><tr><td>Développement Web &amp; Mobile</td><td>1 000 000</td><td>1 100 000</td><td>1 150 000</td></tr><tr><td>Compétences Métiers / Technologies &amp; Outils</td><td>450 000</td><td>500 000</td><td>550 000</td></tr></tbody></table><p>Montants en FCFA, hors taxe. Une modification de tarif est programmée à partir d&#39;une date et ne s&#39;applique qu&#39;aux cohortes ouvertes ensuite.</p><p>La <strong>banque QCM</strong> d&#39;un référentiel contient 20 questions validées. L&#39;import se fait par classeur <code>.xlsx</code>, un onglet par référentiel, puis une validation explicite : importer et valider sont deux actions distinctes. Le fichier importé n&#39;est jamais conservé.</p><h2 id="cohortes-module-2" tabindex="-1">Cohortes (module 2) <a class="header-anchor" href="#cohortes-module-2" aria-label="Permalink to &quot;Cohortes (module 2)&quot;">​</a></h2><p>Une cohorte est une session d&#39;un référentiel, rattachée à une <strong>promotion</strong> annuelle :</p><table tabindex="0"><thead><tr><th>Promotion</th><th>Rentrée</th></tr></thead><tbody><tr><td>Baobab</td><td>Septembre</td></tr><tr><td>Iroko</td><td>Décembre</td></tr><tr><td>Acacia</td><td>Mars</td></tr><tr><td>Karité</td><td>Juin</td></tr></tbody></table><p>Conditions d&#39;ouverture : référentiel publié, banque QCM validée, un prix pour chaque format proposé, au moins un Formateur Principal affecté. Capacité maximale : <strong>15 apprenants</strong>. Les prix de la grille sont figés à l&#39;ouverture.</p><p>Statuts : <strong>ouverte</strong>, <strong>confirmée</strong>, <strong>en cours</strong>, <strong>terminée</strong>, <strong>reportée</strong>, <strong>annulée</strong>.</p><ul><li>Le Coordinateur confirme une cohorte ouverte.</li><li>Une cohorte confirmée démarre seule à sa date de début ; une cohorte en cours se termine seule après sa date de fin.</li><li>Report et annulation sont possibles uniquement avant le démarrage, avec un motif obligatoire, et sont définitifs.</li><li>Une cohorte mêle les trois formats : format et tarif sont portés par chaque inscription.</li></ul><p>La <strong>zone de rentabilité</strong> est recalculée à chaque inscription ou désinscription confirmée :</p><table tabindex="0"><thead><tr><th>Effectif confirmé</th><th>Zone</th></tr></thead><tbody><tr><td>Moins de 7</td><td>Fragile</td></tr><tr><td>7 à 11</td><td>Viable</td></tr><tr><td>12 à 15</td><td>Confortable</td></tr></tbody></table><p>Les seuils Viable et Confortable sont réglables par catégorie. Une cohorte qui démarre fige sa zone et son effectif : les changements de seuil ne touchent que les cohortes à venir.</p><p>Le <strong>tableau de bord de rentabilité</strong> (module 13) montre, pour les cohortes ouvertes et confirmées, la zone, l&#39;effectif, les recettes signées et en attente, le coût de l&#39;encadrement et sa couverture. Une cohorte Fragile à moins d&#39;une semaine du démarrage est signalée « à décider » ; rien n&#39;est déclenché automatiquement.</p><h2 id="candidatures-et-admission-module-18" tabindex="-1">Candidatures et admission (module 18) <a class="header-anchor" href="#candidatures-et-admission-module-18" aria-label="Permalink to &quot;Candidatures et admission (module 18)&quot;">​</a></h2><p>Quatre étapes strictement séquentielles : <strong>dépôt</strong>, <strong>entretien</strong>, <strong>test</strong>, <strong>décision</strong>.</p><ul><li>Entretien sous 5 jours ouvrés, clôturé par le conseiller responsable.</li><li>Test : lien à usage unique, 48 h pour commencer, 2 tentatives de 45 minutes, 10 questions sur 20, seuil indicatif de 60 %.</li><li>Décision motivée sous 3 jours ouvrés.</li><li>Une seule candidature en cours par compte ; redépôt possible 7 jours après un refus.</li><li>Candidature refusée conservée 12 mois, puis anonymisée : les statistiques restent, les données personnelles disparaissent.</li></ul><p>Le déroulé complet est décrit dans <a href="/kura-guide/guide/learner-journey.html">Parcours apprenant</a>.</p><h2 id="inscriptions-et-consentements-module-3" tabindex="-1">Inscriptions et consentements (module 3) <a class="header-anchor" href="#inscriptions-et-consentements-module-3" aria-label="Permalink to &quot;Inscriptions et consentements (module 3)&quot;">​</a></h2><p>L&#39;inscription est créée à l&#39;admission, au statut <strong>en attente de signature</strong>. Statuts : <code>pending_signature</code>, <code>active</code>, <code>suspended</code>, <code>dropped</code>, <code>completed</code>.</p><ul><li>Toute inscription non abandonnée occupe une place ; l&#39;effectif et la zone ne comptent que les inscriptions signées.</li><li>Le format est modifiable jusqu&#39;à la signature, parmi les formats tarifés de la cohorte.</li><li>Deux consentements distincts sont requis avant la signature : réutilisation pédagogique du projet tutoré et droit à l&#39;image. Chaque changement est journalisé.</li><li>Pour un mineur, seuls comptent les consentements du représentant légal, recueillis par un lien email à usage unique de 7 jours.</li><li>Le <strong>financement partagé</strong> désigne un compte organisation au rôle Financeur et sa part (1 à 100 %), figée dans la convention.</li></ul><h2 id="presence-module-4" tabindex="-1">Présence (module 4) <a class="header-anchor" href="#presence-module-4" aria-label="Permalink to &quot;Présence (module 4)&quot;">​</a></h2><ul><li>Les séances virtuelles sont relues chaque heure depuis <code>mod_attendance</code> et ne se modifient pas dans Kura.</li><li>Une séance en présentiel est saisie par un Formateur Principal de la cohorte ou par le Coordinateur, une fois tenue.</li><li>Un retard compte comme une présence ; une absence excusée comme une absence.</li><li>Taux d&#39;absence = minutes manquées ÷ heures du référentiel. L&#39;alerte part <strong>une seule fois</strong> au-delà de 30 %, et se réarme si une correction repasse sous le seuil.</li></ul><h2 id="resultats-module-5" tabindex="-1">Résultats (module 5) <a class="header-anchor" href="#resultats-module-5" aria-label="Permalink to &quot;Résultats (module 5)&quot;">​</a></h2><ul><li>Notes par bloc remontées de Sève par le code <code>KURA-BLOC-{id}</code>, sur 20.</li><li>Moyenne pondérée par la durée des blocs, recalculée à chaque lecture.</li><li>Bloc validé à 10/20, compensable de 8 à 10, éliminatoire sous 8. La note retenue est celle de la dernière tentative notée.</li><li>Repêchage ouvert par un Formateur Principal ou le Coordinateur : bloc sous 10/20, 15 jours après la dernière note, 2 fois au plus. Il est rempli par la première note Sève donnée après son ouverture.</li><li>Jury saisi par le Coordinateur : projet tutoré, soutenance, stage. Ces notes restent <strong>hors moyenne</strong> ; le stage ne bloque pas le certificat.</li></ul><h2 id="certification-module-6" tabindex="-1">Certification (module 6) <a class="header-anchor" href="#certification-module-6" aria-label="Permalink to &quot;Certification (module 6)&quot;">​</a></h2><p>Le certificat exige <strong>quatre conditions cumulatives</strong> :</p><ol><li>moyenne ≥ 10/20 ;</li><li>aucun bloc &lt; 8/20 ;</li><li>soutenance validée ;</li><li>solde intégralement payé.</li></ol><p>Aucune ne compense une autre. Le certificat est délivré une seule fois par le Coordinateur, au nom du président du jury, en PDF scellé. Mentions : Passable dès 10/20, puis Assez bien, Bien et Très bien selon des seuils réglables (12, 14 et 16 par défaut).</p><p>La délivrance termine l&#39;inscription, retire l&#39;apprenant du cours de sa cohorte, fait passer le compte au statut <strong>Canopé</strong> et l&#39;inscrit au Parcours Canopé.</p><p>Une <strong>attestation partielle</strong> est réservée à une inscription abandonnée avec au moins un bloc validé. Un <strong>relevé de compétences</strong> accompagne le certificat ou l&#39;attestation.</p><h2 id="communication-module-8" tabindex="-1">Communication (module 8) <a class="header-anchor" href="#communication-module-8" aria-label="Permalink to &quot;Communication (module 8)&quot;">​</a></h2><ul><li>Annonces du Coordinateur ou de l&#39;Administrateur à une cohorte, ou à toutes les cohortes d&#39;un référentiel.</li><li>Destinataires : inscriptions en attente, actives ou suspendues, et par défaut formateurs et coachs affectés.</li><li>Canaux : email et Sève, envoi immédiat. Pas de WhatsApp pour les annonces.</li><li>Chaque envoi est journalisé, canal par canal, avec son statut et son erreur.</li></ul><h2 id="reporting-et-direction-modules-9-et-15" tabindex="-1">Reporting et Direction (modules 9 et 15) <a class="header-anchor" href="#reporting-et-direction-modules-9-et-15" aria-label="Permalink to &quot;Reporting et Direction (modules 9 et 15)&quot;">​</a></h2><p>Les deux vues sont en <strong>lecture seule</strong>, sur la même période et avec les mêmes définitions.</p><table tabindex="0"><thead><tr><th>Indicateur</th><th>Reporting</th><th>Direction</th></tr></thead><tbody><tr><td>Remplissage, réussite, attestations</td><td>Oui</td><td>Oui</td></tr><tr><td>Facturé, encaissé, reste dû</td><td>Oui</td><td>Oui</td></tr><tr><td>Assiduité, moyenne générale</td><td>Oui</td><td>Oui</td></tr><tr><td>Versé et marge brute</td><td>Non</td><td>Oui</td></tr><tr><td>Portefeuille L&#39;Éclosion</td><td>Non</td><td>Oui</td></tr></tbody></table><p>Le reporting exporte la liste des cohortes en CSV (point-virgule, UTF-8 avec BOM, dans la langue de l&#39;utilisateur).</p><h2 id="remunerations-et-commissions-modules-10-a-12" tabindex="-1">Rémunérations et commissions (modules 10 à 12) <a class="header-anchor" href="#remunerations-et-commissions-modules-10-a-12" aria-label="Permalink to &quot;Rémunérations et commissions (modules 10 à 12)&quot;">​</a></h2><ul><li><strong>Formateurs et coachs</strong> : tarif horaire par zone, forfait projet, forfait coach par apprenant, jeton de jury externe. La grille est paramétrable et chaque taux prend effet à une date. Une cohorte garde les taux et la zone de son démarrage.</li><li><strong>Apporteurs d&#39;affaires</strong> : 5 % des sommes encaissées, tranche par tranche, part du financeur comprise. Un remboursement reprend la commission par une ligne négative.</li><li><strong>Partenaires marketing</strong> : rémunération sur dépôt de facture, dans la limite du contrat ou du forfait de campagne ; validation ou rejet motivé par le Coordinateur.</li></ul><p>Le détail des calculs et des versements est dans <a href="/kura-guide/guide/billing.html#remunerations-et-commissions">Facturation</a>.</p>',46)])])}const h=t(n,[["render",s]]);export{p as __pageData,h as default};
